arguments.old_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
builder.Services.AddHttpClient("api")
    .ConfigureHttpMessageHandlerBuilder(b =>
    {
        ((HttpClientHandler)b.PrimaryHandler).UseCookies = false;
    });
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

arguments.new_str:
var builder = WebApplication.CreateBuilder(args);

// Fix #2: Scoped IUserService was captured by singleton ICacheService.
// .NET 9 enables ValidateScopes in development, which catches this at startup.
// Use a factory that resolves IUserService per-request from the scope instead.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// Fix #1: HttpClientFactory now uses SocketsHttpHandler by default in .NET 9.
// The old cast to HttpClientHandler throws InvalidCastException at runtime.
// Use ConfigurePrimaryHttpMessageHandler to set the handler type explicitly.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });

// Fix #3: ForwardedHeaders middleware now ignores headers from unknown proxies.
// Add your reverse-proxy addresses to KnownProxies so headers are processed.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // TODO: Replace with your actual reverse-proxy IP address(es).
    options.KnownProxies.Add(System.Net.IPAddress.Parse("10.0.0.1"));
});

// Fix #4: Trace-level HttpClientFactory logs now redact all header values.
// Explicitly allow the non-sensitive headers you need to see when debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id"
        && h != "X-Correlation-Id"
        && h != "Content-Type"
        && h != "Accept"));

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

